package com.isc.identityreference.governance;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import org.springframework.stereotype.Component; import java.time.Instant; import java.util.*; import java.util.concurrent.ConcurrentLinkedDeque;
@Component @ConditionalOnProperty(prefix="identity-reference.persistence.oracle",name="enabled",havingValue="false",matchIfMissing=true)
public final class InMemoryAuditEventStore implements AuditEventStore { private final ConcurrentLinkedDeque<AuditEvent> events=new ConcurrentLinkedDeque<>(); public void append(AuditEvent e){events.addLast(e);} public int purgeBefore(Instant c,int limit){int n=0;while(n<limit){var e=events.peekFirst();if(e==null||!e.occurredAt().isBefore(c))break;if(events.remove(e))n++;}return n;} public List<AuditEvent> recent(int limit){List<AuditEvent> r=new ArrayList<>();var i=events.descendingIterator();while(i.hasNext()&&r.size()<limit)r.add(i.next());return List.copyOf(r);} }
